-- PENDING: NOT APPLIED. Invoker-only, same filters and same RLS. No increased timeout.
-- Reuse one visible-row snapshot for all totals, status/need tabs, selectors and personal counters.
CREATE OR REPLACE FUNCTION signal_list_counts(_filter jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ WITH visible AS MATERIALIZED (SELECT * FROM opportunity_signals),base AS MATERIALIZED(SELECT * FROM (SELECT s.* FROM visible s CROSS JOIN (SELECT _filter-'quick'-'status' AS value) f WHERE coalesce((f.value->>'cancelled')::boolean,false)=(s.cancelled_at IS NOT NULL) AND (coalesce(f.value->>'q','')='' OR strpos(lower(s.customer_name),lower(btrim(f.value->>'q')))>0 OR strpos(s.phone,btrim(f.value->>'q'))>0) AND (coalesce(f.value->>'from','')='' OR CASE WHEN f.value->>'basis'='closed' THEN (s.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date ELSE s.detected_on END>=(f.value->>'from')::date) AND (coalesce(f.value->>'to','')='' OR CASE WHEN f.value->>'basis'='closed' THEN (s.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date ELSE s.detected_on END<=(f.value->>'to')::date) AND (coalesce(f.value->>'source','')='' OR s.source=f.value->>'source') AND (coalesce(f.value->>'product','')='' OR f.value->>'product'=ANY(s.products)) AND (coalesce(f.value->>'needGroup','')='' OR f.value->>'needGroup'=ANY(CASE WHEN cardinality(s.need_groups)>0 THEN s.need_groups ELSE array_remove(ARRAY[s.need_group],NULL) END)) AND (coalesce(f.value->>'saleId','')='' OR s.assigned_to::text=f.value->>'saleId') AND (coalesce(f.value->>'creatorId','')='' OR s.created_by::text=f.value->>'creatorId') AND (NOT coalesce((f.value->>'unassigned')::boolean,false) OR s.assigned_to IS NULL) AND (coalesce(f.value->>'lostReason','')='' OR CASE WHEN s.lost_reason LIKE 'Khác%' THEN 'Khác' ELSE s.lost_reason END=f.value->>'lostReason') AND (coalesce(f.value->>'potential','')='' OR coalesce(s.potential,'unrated')=f.value->>'potential') AND (coalesce(f.value->>'labelId','')='' OR EXISTS(SELECT 1 FROM signal_label_links l WHERE l.signal_id=s.id AND l.label_id::text=f.value->>'labelId')) AND (coalesce(f.value->>'stage','')='' OR CASE WHEN s.status IS NULL OR s.status IN ('waiting','contacting') THEN 'intake' WHEN s.status IN ('consulting','quoted') THEN 'advice' WHEN s.status='lost' THEN 'ended' ELSE 'closing' END=f.value->>'stage') AND (coalesce(f.value->>'status',f.value->>'quick','all') IN ('','all') OR CASE WHEN coalesce(f.value->>'status',f.value->>'quick')='unassigned' THEN s.assigned_to IS NULL AND s.status IS NULL ELSE s.status=coalesce(f.value->>'status',f.value->>'quick') END) AND (coalesce(f.value->>'nextFrom','')='' OR s.next_contact_on>=(f.value->>'nextFrom')::date) AND (coalesce(f.value->>'nextTo','')='' OR s.next_contact_on<=(f.value->>'nextTo')::date) AND (coalesce(f.value->>'work','all')='all' OR (f.value->>'work'='high' AND s.potential='high') OR (f.value->>'work'='won' AND s.status='won') OR (f.value->>'work'='overdue' AND s.status IN ('waiting','contacting','consulting','quoted','deposit') AND s.next_contact_on<(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date) OR (f.value->>'work'='action' AND s.status IN ('waiting','contacting','consulting','quoted','deposit') AND (s.next_contact_on<=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date OR (s.potential='high' AND s.next_contact_on IS NULL)))))),needs AS MATERIALIZED(SELECT * FROM (SELECT s.* FROM visible s CROSS JOIN (SELECT _filter-'needGroup' AS value) f WHERE coalesce((f.value->>'cancelled')::boolean,false)=(s.cancelled_at IS NOT NULL) AND (coalesce(f.value->>'q','')='' OR strpos(lower(s.customer_name),lower(btrim(f.value->>'q')))>0 OR strpos(s.phone,btrim(f.value->>'q'))>0) AND (coalesce(f.value->>'from','')='' OR CASE WHEN f.value->>'basis'='closed' THEN (s.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date ELSE s.detected_on END>=(f.value->>'from')::date) AND (coalesce(f.value->>'to','')='' OR CASE WHEN f.value->>'basis'='closed' THEN (s.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date ELSE s.detected_on END<=(f.value->>'to')::date) AND (coalesce(f.value->>'source','')='' OR s.source=f.value->>'source') AND (coalesce(f.value->>'product','')='' OR f.value->>'product'=ANY(s.products)) AND (coalesce(f.value->>'needGroup','')='' OR f.value->>'needGroup'=ANY(CASE WHEN cardinality(s.need_groups)>0 THEN s.need_groups ELSE array_remove(ARRAY[s.need_group],NULL) END)) AND (coalesce(f.value->>'saleId','')='' OR s.assigned_to::text=f.value->>'saleId') AND (coalesce(f.value->>'creatorId','')='' OR s.created_by::text=f.value->>'creatorId') AND (NOT coalesce((f.value->>'unassigned')::boolean,false) OR s.assigned_to IS NULL) AND (coalesce(f.value->>'lostReason','')='' OR CASE WHEN s.lost_reason LIKE 'Khác%' THEN 'Khác' ELSE s.lost_reason END=f.value->>'lostReason') AND (coalesce(f.value->>'potential','')='' OR coalesce(s.potential,'unrated')=f.value->>'potential') AND (coalesce(f.value->>'labelId','')='' OR EXISTS(SELECT 1 FROM signal_label_links l WHERE l.signal_id=s.id AND l.label_id::text=f.value->>'labelId')) AND (coalesce(f.value->>'stage','')='' OR CASE WHEN s.status IS NULL OR s.status IN ('waiting','contacting') THEN 'intake' WHEN s.status IN ('consulting','quoted') THEN 'advice' WHEN s.status='lost' THEN 'ended' ELSE 'closing' END=f.value->>'stage') AND (coalesce(f.value->>'status',f.value->>'quick','all') IN ('','all') OR CASE WHEN coalesce(f.value->>'status',f.value->>'quick')='unassigned' THEN s.assigned_to IS NULL AND s.status IS NULL ELSE s.status=coalesce(f.value->>'status',f.value->>'quick') END) AND (coalesce(f.value->>'nextFrom','')='' OR s.next_contact_on>=(f.value->>'nextFrom')::date) AND (coalesce(f.value->>'nextTo','')='' OR s.next_contact_on<=(f.value->>'nextTo')::date) AND (coalesce(f.value->>'work','all')='all' OR (f.value->>'work'='high' AND s.potential='high') OR (f.value->>'work'='won' AND s.status='won') OR (f.value->>'work'='overdue' AND s.status IN ('waiting','contacting','consulting','quoted','deposit') AND s.next_contact_on<(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date) OR (f.value->>'work'='action' AND s.status IN ('waiting','contacting','consulting','quoted','deposit') AND (s.next_contact_on<=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date OR (s.potential='high' AND s.next_contact_on IS NULL)))))),st AS(SELECT coalesce(status,'unassigned') key,count(*) n FROM base GROUP BY status),ng AS(SELECT g key,count(DISTINCT s.id) n FROM needs s CROSS JOIN LATERAL unnest(CASE WHEN cardinality(s.need_groups)>0 THEN s.need_groups ELSE array_remove(ARRAY[s.need_group],NULL) END) g GROUP BY g),mine AS(SELECT * FROM visible WHERE assigned_to=auth.uid() AND cancelled_at IS NULL) SELECT jsonb_build_object('total',(SELECT count(*) FROM (SELECT s.* FROM visible s CROSS JOIN (SELECT _filter AS value) f WHERE coalesce((f.value->>'cancelled')::boolean,false)=(s.cancelled_at IS NOT NULL) AND (coalesce(f.value->>'q','')='' OR strpos(lower(s.customer_name),lower(btrim(f.value->>'q')))>0 OR strpos(s.phone,btrim(f.value->>'q'))>0) AND (coalesce(f.value->>'from','')='' OR CASE WHEN f.value->>'basis'='closed' THEN (s.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date ELSE s.detected_on END>=(f.value->>'from')::date) AND (coalesce(f.value->>'to','')='' OR CASE WHEN f.value->>'basis'='closed' THEN (s.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date ELSE s.detected_on END<=(f.value->>'to')::date) AND (coalesce(f.value->>'source','')='' OR s.source=f.value->>'source') AND (coalesce(f.value->>'product','')='' OR f.value->>'product'=ANY(s.products)) AND (coalesce(f.value->>'needGroup','')='' OR f.value->>'needGroup'=ANY(CASE WHEN cardinality(s.need_groups)>0 THEN s.need_groups ELSE array_remove(ARRAY[s.need_group],NULL) END)) AND (coalesce(f.value->>'saleId','')='' OR s.assigned_to::text=f.value->>'saleId') AND (coalesce(f.value->>'creatorId','')='' OR s.created_by::text=f.value->>'creatorId') AND (NOT coalesce((f.value->>'unassigned')::boolean,false) OR s.assigned_to IS NULL) AND (coalesce(f.value->>'lostReason','')='' OR CASE WHEN s.lost_reason LIKE 'Khác%' THEN 'Khác' ELSE s.lost_reason END=f.value->>'lostReason') AND (coalesce(f.value->>'potential','')='' OR coalesce(s.potential,'unrated')=f.value->>'potential') AND (coalesce(f.value->>'labelId','')='' OR EXISTS(SELECT 1 FROM signal_label_links l WHERE l.signal_id=s.id AND l.label_id::text=f.value->>'labelId')) AND (coalesce(f.value->>'stage','')='' OR CASE WHEN s.status IS NULL OR s.status IN ('waiting','contacting') THEN 'intake' WHEN s.status IN ('consulting','quoted') THEN 'advice' WHEN s.status='lost' THEN 'ended' ELSE 'closing' END=f.value->>'stage') AND (coalesce(f.value->>'status',f.value->>'quick','all') IN ('','all') OR CASE WHEN coalesce(f.value->>'status',f.value->>'quick')='unassigned' THEN s.assigned_to IS NULL AND s.status IS NULL ELSE s.status=coalesce(f.value->>'status',f.value->>'quick') END) AND (coalesce(f.value->>'nextFrom','')='' OR s.next_contact_on>=(f.value->>'nextFrom')::date) AND (coalesce(f.value->>'nextTo','')='' OR s.next_contact_on<=(f.value->>'nextTo')::date) AND (coalesce(f.value->>'work','all')='all' OR (f.value->>'work'='high' AND s.potential='high') OR (f.value->>'work'='won' AND s.status='won') OR (f.value->>'work'='overdue' AND s.status IN ('waiting','contacting','consulting','quoted','deposit') AND s.next_contact_on<(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date) OR (f.value->>'work'='action' AND s.status IN ('waiting','contacting','consulting','quoted','deposit') AND (s.next_contact_on<=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date OR (s.potential='high' AND s.next_contact_on IS NULL)))))),'status',coalesce((SELECT jsonb_object_agg(key,n) FROM st),'{}')||jsonb_build_object('all',(SELECT count(*) FROM base)),'needs',coalesce((SELECT jsonb_object_agg(key,n) FROM ng),'{}')||jsonb_build_object('all',(SELECT count(*) FROM needs)),'sales',coalesce((SELECT jsonb_agg(DISTINCT assigned_to) FILTER(WHERE assigned_to IS NOT NULL) FROM visible),'[]'),'creators',coalesce((SELECT jsonb_agg(DISTINCT created_by) FROM visible),'[]'),'mine',jsonb_build_object('waiting',(SELECT count(*) FROM mine WHERE status='waiting'),'active',(SELECT count(*) FROM mine WHERE status IN ('contacting','consulting','quoted','deposit')),'quoted',(SELECT count(*) FROM mine WHERE status='quoted'),'won',(SELECT count(*) FROM mine WHERE status='won' AND date_trunc('month',closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')=date_trunc('month',now() AT TIME ZONE 'Asia/Ho_Chi_Minh')))) $$;
